  'tr.h': 'Measurement threshold', 'tr.sub': 'If only trees above a diameter (or between two thresholds) were measured, declare it here. The threshold belongs to the observation: it is not the support bound of the distribution (e.g. Weibull a, beta L) nor the smallest diameter in the data. With thresholded data fitting uses the conditional likelihood; cutting the chart alone is not right.',
  'tr.mode.none': 'No threshold (all trees measured)', 'tr.mode.lower': 'Lower threshold: only d ≥ L measured', 'tr.mode.both': 'Lower and upper thresholds: only L ≤ d ≤ U measured',
  'tr.L': 'L, lower threshold (cm)', 'tr.U': 'U, upper threshold (cm)', 'tr.n.h': 'What does N represent?',
  'tr.n.observed': 'Trees above the threshold (measured n)', 'tr.n.population': 'The whole population (including below the threshold, estimated as n / P(L ≤ D ≤ U))',
  'tr.on': 'Threshold declared: only the conditional maximum likelihood methods run. The closed-form methods valid for untruncated data (ML, moments, percentiles) are not valid for truncated observations and are disabled; filling recovery targets from raw data is disabled too.',
  'tr.off': 'Without a threshold every method can be used.', 'tr.disabled': 'not valid for truncated data (no conditional version); disabled while a threshold is declared',
  'tr.nofill': 'Filling from raw data is disabled because a measurement threshold is declared: the mean and percentiles of a thresholded sample are not summaries of the whole distribution.',
  'd.n.tr': 'n (measured, inside the threshold)',
  'dg.trunc': p => `threshold ${p.L} ≤ d ≤ ${p.U} cm; under the fitted distribution P(inside the threshold) = ${p.m}; measured n = ${p.n}, estimated total including outside the threshold = ${p.N}; scope of N: ${p.s}`,
  'pr.trunc.none': 'enter a threshold value', 'pr.trunc.lower': 'the lower threshold must be zero or a positive number', 'pr.trunc.upper': 'the upper threshold must be a positive number',
  'pr.trunc.order': p => `the upper threshold (${p.upper}) must exceed the lower (${p.lower})`, 'pr.trunc.outside': p => `${p.count} diameters outside the declared threshold (e.g. ${p.example} cm); the threshold or the data are wrong`,
  'pr.trunc.nostart': 'no untruncated estimate for a start', 'w.trunc.noconverge': 'the conditional likelihood could not be maximised; no parameters are given', 'w.trunc.boundary': 'the conditional solution ran to a parameter bound; no parameters are given',
  'sol.nelder-mead': 'Nelder–Mead', 'x.trunc': 'Measurement threshold', 'x.trlo': 'Lower threshold (cm)', 'x.trhi': 'Upper threshold (cm)', 'x.mass': 'P(inside the threshold)', 'x.nscope': 'N (chosen scope)',
