  'st.fit': 'Regression method', 'st.fit.nls': 'NLS (each response separately, original scale)', 'st.fit.sur': 'SUR (responses together, covariance between equations)', 'st.fit.logols': 'log-OLS (on ln y; a different objective)',
  'st.back.median': 'Back-transformation: median exp(Zβ)', 'st.back.mean': 'Back-transformation: mean exp(Zβ + s²/2)', 'st.K': 'Number of validation folds',
