  'st.need.terms': 'Choose at least one term.', 'st.need.col': p => `Choose the ${p.k} column.`, 'st.need.xi': 'Enter ξ (lower bound) for the Johnson SB.', 'st.need.a': 'Enter zero or a positive value for the location a.',
