  'st.pr.stand.var.missing': p => `${p.key} empty or unreadable`, 'st.pr.stand.var.varies': p => `${p.key} takes different values within the unit`, 'st.pr.stand.var.nonpos': p => `${p.key} zero or negative`, 'st.pr.stand.x.missing': p => `stand variable missing${p.keys ? ': ' + p.keys : ''}`,
  'st.pr.stand.target.none': 'targets could not be computed (e.g. very few trees or equal diameters)', 'st.pr.stand.few': p => `No model trained: at least 2 plots and more units than coefficients (${p.p}) are needed (${p.units} units, ${p.plots} plots).`,
  'st.pr.stand.xi': 'The Johnson SB needs ξ.', 'st.pr.stand.fit': 'The regression did not converge.', 'st.pr.stand.order': p => `predicted ${p.hi} not above ${p.lo}`, 'st.pr.stand.dq': 'predicted Dq not above the mean diameter',
  'st.pr.stand.dmin': 'predicted Dmin not below the smallest percentile', 'st.pr.stand.cv.few': 'Validation needs at least 2 plots.',
  'st.fit.cdfr': 'CDFR (Poudel and Cao: coefficients shared by the plots, distance between cumulative distributions)', 'st.fit.mcdfr': 'Modified CDFR (Poudel and Cao: with diameter classes)', 'st.width': 'Class width (cm)',
