  'st.need.width': 'Enter a positive class width.', 'st.need.cdfwb': 'CDFR and modified CDFR are for the Weibull routes only.', 'st.busy': 'Training and validating the model…', 'st.cancelled': 'Training cancelled.',
  'st.res.cdf': p => `Objective ${p.s} at the NLS start, ${p.o} at the end (${p.i} iterations; ${p.r} steps rejected because a recovery could not be solved)${p.w}.`, 'st.res.width': p => `; class width ${p.w} cm, the last class left out of the objective only`,
  'st.res.oneclass': p => `${p.n} units fell into one class and did not enter this objective.`, 'st.res.dminfixed': 'The Dmin equation was fitted by NLS and held fixed.',
  'st.res.note.cdfr': 'Coefficients shared by all plots, minimising the distance between cumulative distributions (weight 1/n per plot, positions (j − 0.5)/n). No standard errors. RMSE and bias on the targets, on the training data.',
