  'st.pr.stand.cdf.startfail': p => `At the NLS start the recovery could not be solved for some units (${Object.entries(p.fails || {}).map(([k, v]) => `${k}: ${v}`).join(', ')}); several solutions are not chosen by a rule, so no model was trained.`,
  'st.pr.stand.cdf.start': 'No NLS start was found.', 'st.pr.stand.cdf.family': 'CDFR is for the Weibull routes only.', 'st.pr.stand.cdf.oneclass': 'one class',
  'm.weibull.lmom': 'L-moments', 'm.gamma.lmom': 'L-moments', 'm.normal.qme': 'General quantile matching (QME)', 'm.gamma.qme': 'General quantile matching (QME)', 'm.beta.qme': 'General quantile matching (QME)',
  'm.normal.mge': 'Minimum distance (MGE)', 'm.gamma.mge': 'Minimum distance (MGE)', 'm.beta.mge': 'Minimum distance (MGE)',
  'mnote.weibull.lmom': 'Sample L-moments ℓ1, ℓ2 of y = d − a (from probability-weighted moments, unbiased); c = −ln 2 / ln(1 − ℓ2/ℓ1), b = ℓ1/Γ(1 + 1/c). A method apart from moments and maximum likelihood.',
  'mnote.gamma.lmom': 'ℓ2/ℓ1 = Γ(k + ½)/(√π Γ(k + 1)) is solved exactly for k (one root), θ = ℓ1/k. The exact equation is used instead of the rational approximation in lmomco.',
  'mnote.normal.qme': 'The weighted sum of squares between the sample quantiles (type 7) and the distribution\'s quantiles at your probabilities is minimised (Nelder–Mead, start from the moments).', 'mnote.gamma.qme': 'The weighted sum of squares between the sample quantiles (type 7) and the distribution\'s quantiles at your probabilities is minimised (Nelder–Mead, start from the moments).', 'mnote.beta.qme': 'The weighted sum of squares between the sample quantiles (type 7) and the distribution\'s quantiles at your probabilities is minimised; L and U fixed.',
  'mnote.normal.mge': 'The distance you choose (KS, Cramér–von Mises or Anderson–Darling) is minimised. That it looks good on this criterion in the comparison table is by construction; the table marks it.', 'mnote.gamma.mge': 'The distance you choose (KS, Cramér–von Mises or Anderson–Darling) is minimised. That it looks good on this criterion in the comparison table is by construction; the table marks it.', 'mnote.beta.mge': 'The distance you choose is minimised; L and U fixed. That it looks good on this criterion in the comparison table is by construction; the table marks it.',
  'opt.probs': 'Probabilities', 'opt.weights': 'Weights (empty = equal)', 'opt.gof': 'Distance', 'opt.gof.ks': 'KS D', 'opt.gof.cvm': 'Cramér–von Mises W²', 'opt.gof.ad': 'Anderson–Darling A²',
  'opt.note.normal.qme': 'Probabilities between 0 and 1, increasing, at least two; weights positive and as many as the probabilities (separate with spaces or ";").', 'opt.note.gamma.qme': 'Probabilities between 0 and 1, increasing, at least two; weights positive and as many as the probabilities.', 'opt.note.beta.qme': 'Probabilities between 0 and 1, increasing, at least two; weights positive and as many as the probabilities.',
  'opt.note.normal.mge': 'The minimised criterion is written to the result record.', 'opt.note.gamma.mge': 'The minimised criterion is written to the result record.', 'opt.note.beta.mge': 'The minimised criterion is written to the result record.',
  'est.lmom': 'L-moments', 'est.qme': 'general quantile matching', 'est.mge': 'minimum distance',
  'set.probs': p => `probabilities ${[].concat(p.v).join(', ')}`, 'set.weights': p => `weights ${[].concat(p.v).join(', ')}`, 'set.gof': p => `by ${{ ks: 'KS', cvm: 'CvM', ad: 'AD' }[p.v] || p.v}`,
  'pr.qme.probs': 'probabilities must lie between 0 and 1', 'pr.qme.order': 'probabilities must increase', 'pr.qme.few': p => `at least ${p.k} probabilities are needed (${p.m} given)`, 'pr.qme.weights': p => `${p.m} positive weights are needed`, 'pr.qme.ident': 'the sample quantiles at the chosen probabilities do not identify two parameters (equal values)',
  'pr.lmom.ratio': 'the ratio ℓ2/ℓ1 is not between 0 and 1', 'pr.d.le.a': p => `${p.count} diameters not above the location a = ${p.a} cm (e.g. ${p.example} cm)`, 'pr.start.none': 'no starting value from the moments',
  'w.lmom.overflow': 'the L-moment solution overflowed; no parameters are given', 'w.lmom.kbound': 'the shape k lies outside the search interval (10⁻⁴–10⁸); no parameters are given',
  'cmp.selfcrit': '† This row was fitted by minimising this criterion; that it looks good on it is by construction.', 'list.bad': 'list not readable',
  'rg.tab.fns': 'Johnson SB (Fonseca, 4 parameters)', 'rg.in.fns': 'Mean, median, Dq and the basal-area-weighted mean diameter d̄_G', 'rg.out.fns': 'Johnson SB, Fonseca et al. (2009): all four parameters including ξ (tab 4)',
  'm.johnsonsb.fonseca': 'Fonseca et al. (2009): four parameters', 'fns.h': 'Johnson SB: all-parameter recovery, Fonseca, Marques and Parresol (2009)',
  'fns.sub': 'ξ, λ, γ and δ are recovered together from the median and the first three noncentral moments. A method apart from Parresol (2003): there ξ is given by you, here it is estimated.',
  'fns.f.dg': 'Basal-area-weighted mean diameter d̄_G (cm)', 'fns.k.mean': 'mean', 'fns.k.median': 'median', 'fns.k.dq': 'Dq', 'fns.k.dg': 'd̄_G',
  'fns.n.eq': 'Equations (source, 6, 7, 9, 11): γ = δ ln(1/y₅₀ − 1); ξ + λμ′₁ = d̄; ξ² + 2ξλμ′₁ + λ²μ′₂ = Dq²; ξ³ + 3ξ²λμ′₁ + 3ξλ²μ′₂ + λ³μ′₃ = d̄_G·Dq². μ′ᵣ are the noncentral moments of Y = (D − ξ)/λ.',
  'fns.n.dg': 'd̄_G = Σgᵢdᵢ / Σgᵢ (gᵢ the basal area of tree i); the third noncentral moment m₃ = d̄_G·Dq². m₃ is never derived from the mean and the variance: without d̄_G nothing is computed.',
